ee:message.ee:set-payload:
%dw 2.0
output application/json
//function to remove duplicates by Id
fun uniqueById(arr) = 
  arr filter ((item, idx) -> 
    indexOf((arr map (i) -> i.Id), item.Id) == idx
  )
---
[{
	"Level1Descriptor": uniqueById(
      vars.filteredBusinessUnits filter ((item) -> (item.Level1Descriptor != null and item.Level1Descriptor.Id != null) or (item.Level == 1 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level1Descriptor.Id) ) (item.Descriptor.Id)else(item.Level1Descriptor.Id),
		Name: if ( isEmpty(item.Level1Descriptor.Name) ) (item.Descriptor.Name)else(item.Level1Descriptor.Name),
		ParentId: null
	})
    )
},
  {
	"Level2Descriptor": uniqueById(
      vars.filteredBusinessUnits filter ((item) -> (item.Level2Descriptor != null and item.Level2Descriptor.Id != null) or (item.Level == 2 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level2Descriptor.Id) ) (item.Descriptor.Id)else(item.Level2Descriptor.Id),
		Name: if ( isEmpty(item.Level2Descriptor.Name) ) (item.Descriptor.Name)else(item.Level2Descriptor.Name),
		ParentId: if ( item.Level1Descriptor.Id != null ) item.Level1Descriptor.Id else null // should ideally be not null
	})
    )
},
  {
	"Level3Descriptor": uniqueById(
      vars.filteredBusinessUnits filter ((item) -> (item.Level3Descriptor != null and item.Level3Descriptor.Id != null) or (item.Level == 3 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level3Descriptor.Id) ) (item.Descriptor.Id)else(item.Level3Descriptor.Id),
		Name: if ( isEmpty(item.Level3Descriptor.Name) ) (item.Descriptor.Name)else(item.Level3Descriptor.Name),
		ParentId: if ( item.Level2Descriptor != null ) item.Level2Descriptor.Id else null
	})
    )
},
  {
	"Level4Descriptor": uniqueById(
      vars.filteredBusinessUnits filter ((item) -> (item.Level4Descriptor != null and item.Level4Descriptor.Id != null) or (item.Level == 4 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level4Descriptor.Id) ) (item.Descriptor.Id)else(item.Level4Descriptor.Id),
		Name: if ( isEmpty(item.Level4Descriptor.Name) ) (item.Descriptor.Name)else(item.Level4Descriptor.Name),
		ParentId: if ( item.Level3Descriptor != null ) item.Level3Descriptor.Id else null
	})
    )
},
  {
	"Level5Descriptor": uniqueById(
      vars.filteredBusinessUnits filter((item) -> (item.Level5Descriptor != null and item.Level5Descriptor.Id != null) or (item.Level == 5 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level5Descriptor.Id) ) (item.Descriptor.Id)else(item.Level5Descriptor.Id),
		Name: if ( isEmpty(item.Level5Descriptor.Name) ) (item.Descriptor.Name)else(item.Level5Descriptor.Name),
		ParentId: if ( item.Level4Descriptor != null ) item.Level4Descriptor.Id else null
	})
    )
},
  {
	"Level6Descriptor": uniqueById(
      vars.filteredBusinessUnits filter ((item) -> (item.Level6Descriptor != null and item.Level6Descriptor.Id != null) or (item.Level == 6 and !isEmpty(item.Descriptor.Id))) map ((item) -> {
		Id: if ( isEmpty(item.Level6Descriptor.Id) ) (item.Descriptor.Id)else(item.Level6Descriptor.Id),
		Name: if ( isEmpty(item.Level6Descriptor.Name) ) (item.Descriptor.Name)else(item.Level6Descriptor.Name),
		ParentId: if ( item.Level5Descriptor != null ) item.Level5Descriptor.Id else null
	})
    )
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
vars.sfResponse map((item,index) ->
	{
		"Id": item.Id,
		"Active__c": false
	}
)

ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Binaries
output application/json
var emailContent = vars.duplicateBusinessUnits map((item,index)
-> {
	"S No": index +1 default "",
	"BusinessUnitCode": item.Descriptor.Id default "",
	"Name": item.Descriptor.Name default "",
	"Level": item.Level default ""
})
---
{
	"to": p('email.businessUsers.to'),
	"cc": p('email.businessUsers.cc'),
	"subject": p('email.buDuplicates.subject') ++ vars.correlationId,
	"body": p('email.buDuplicates.body'),
	"attachments": [{
		"filename": "BusinessUnitDuplicates_Report.csv",
		"content": toBase64(write(emailContent,"application/csv",{
			header: true
		})),
		"contentType": "plain/text"
	}]
}
